package com.brasa.restaurant.service;import com.brasa.restaurant.dto.Dtos.*;import com.brasa.restaurant.enums.Enums.StatusPedido;import com.brasa.restaurant.model.*;import com.brasa.restaurant.repository.Repositories.*;import com.brasa.restaurant.security.SecurityUtils;import org.springframework.stereotype.Service;import java.math.*;import java.time.*;import java.time.format.TextStyle;import java.util.*;import java.util.stream.*;@Service public class DashboardService{private final PedidoRepository orders;private final ProdutoRepository products;private final CategoriaRepository categories;public DashboardService(PedidoRepository o,ProdutoRepository p,CategoriaRepository c){orders=o;products=p;categories=c;}public DashboardResponse summary(String periodo){String r=SecurityUtils.current().restaurantId();ZoneId zone=ZoneId.of("America/Recife");LocalDate today=LocalDate.now(zone);Instant dayStart=today.atStartOfDay(zone).toInstant(),dayEnd=today.plusDays(1).atStartOfDay(zone).toInstant();List<Pedido>all=orders.findByRestauranteIdOrderByCriadoEmDesc(r);List<Pedido>todayOrders=all.stream().filter(p->!p.getCriadoEm().isBefore(dayStart)&&p.getCriadoEm().isBefore(dayEnd)&&p.getStatus()!=StatusPedido.CANCELADO).toList();BigDecimal day=sum(todayOrders);BigDecimal week=sum(all.stream().filter(p->p.getCriadoEm().isAfter(today.minusDays(6).atStartOfDay(zone).toInstant())&&p.getStatus()!=StatusPedido.CANCELADO).toList());BigDecimal ticket=todayOrders.isEmpty()?BigDecimal.ZERO:day.divide(BigDecimal.valueOf(todayOrders.size()),2,RoundingMode.HALF_UP);long active=all.stream().filter(p->p.getStatus()==StatusPedido.PENDENTE||p.getStatus()==StatusPedido.PREPARANDO).count();List<HoraDto>hours=IntStream.rangeClosed(11,23).mapToObj(h->{var list=todayOrders.stream().filter(p->p.getCriadoEm().atZone(zone).getHour()==h).toList();return new HoraDto(h+"h",list.size(),sum(list));}).toList();List<DiaDto>weekDays=IntStream.range(0,7).mapToObj(i->{LocalDate d=today.with(DayOfWeek.MONDAY).plusDays(i);var list=all.stream().filter(p->p.getCriadoEm().atZone(zone).toLocalDate().equals(d)&&p.getStatus()!=StatusPedido.CANCELADO).toList();String label=d.getDayOfWeek().getDisplayName(TextStyle.SHORT,new Locale("pt","BR"));return new DiaDto(label,sum(list));}).toList();Map<String,Long>qty=new HashMap<>();Map<String,BigDecimal>revenue=new HashMap<>();all.stream().filter(p->p.getStatus()!=StatusPedido.CANCELADO).flatMap(p->p.getItens().stream()).forEach(i->{qty.merge(i.getProdutoId(),(long)i.getQuantidade(),Long::sum);revenue.merge(i.getProdutoId(),i.getPrecoUnitario().multiply(BigDecimal.valueOf(i.getQuantidade())),BigDecimal::add);});Map<String,Produto>pm=products.findByRestauranteIdOrderByNomeAsc(r).stream().collect(Collectors.toMap(Produto::getId,x->x));Map<String,String>cm=categories.findByRestauranteIdOrderByOrdemAsc(r).stream().collect(Collectors.toMap(Categoria::getId,Categoria::getNome));List<RankingDto>rank=qty.entrySet().stream().sorted(Map.Entry.<String,Long>comparingByValue().reversed()).limit(10).map(e->{Produto p=pm.get(e.getKey());return new RankingDto(e.getKey(),p==null?"Produto removido":p.getNome(),p==null?null:p.getImagemUrl(),p==null?"-":cm.getOrDefault(p.getCategoriaId(),"-"),e.getValue(),revenue.getOrDefault(e.getKey(),BigDecimal.ZERO));}).toList();return new DashboardResponse(day,0,week,ticket,todayOrders.size(),active,hours,weekDays,rank);}private BigDecimal sum(List<Pedido>list){return list.stream().map(Pedido::getTotal).reduce(BigDecimal.ZERO,BigDecimal::add);}}
